<div class="socio-historial"><header class="encabezado"><h2>Tu actividad</h2><p>Un resumen de tus préstamos, inscripciones, compras y publicaciones.</p></header>
<section class="panel socio-historial__grupo" aria-labelledby="historial-prestamos"><h3 class="panel__titulo" id="historial-prestamos">Préstamos</h3>@if ($prestamos->isEmpty())<p class="texto-suave">No tienes préstamos registrados.</p>@else<div class="tabla-envoltura"><table class="tabla tabla--apilada"><thead><tr><th>Libro</th><th>ISBN</th><th>Préstamo</th><th>Devolución</th><th>Estado</th><th></th></tr></thead><tbody>@foreach ($prestamos as $prestamo)<tr><td data-label="Libro">{{ $prestamo->libro->titulo ?? 'Libro no disponible' }}</td><td data-label="ISBN">{{ $prestamo->libro->isbn ?? '—' }}</td><td data-label="Préstamo">{{ $prestamo->fecha_prestamo?->format('d/m/Y') ?? '—' }}</td><td data-label="Devolución">{{ $prestamo->fecha_devolucion_real?->format('d/m/Y') ?? 'Pendiente' }}</td><td data-label="Estado">{{ $prestamo->fecha_devolucion_real ? 'Devuelto' : 'Activo' }}</td><td data-label="Acciones">@if ($prestamo->libro)<a class="boton boton--linea boton--pequeno" href="{{ route('libro.paginaInterna', $prestamo->libro->id) }}">Ver libro</a>@endif</td></tr>@endforeach</tbody></table></div>@endif</section>
<section class="panel socio-historial__grupo" aria-labelledby="historial-eventos"><h3 class="panel__titulo" id="historial-eventos">Inscripciones a eventos</h3>@if ($eventosInscritos->isEmpty())<p class="texto-suave">No tienes inscripciones a eventos.</p>@else<div class="tabla-envoltura"><table class="tabla tabla--apilada"><thead><tr><th>Evento</th><th>Lugar</th><th>Fecha</th><th>Estado</th><th></th></tr></thead><tbody>@foreach ($eventosInscritos as $evento)<tr><td data-label="Evento">{{ $evento->titulo }}</td><td data-label="Lugar">{{ $evento->ubicacion ?: 'Sin ubicación' }}</td><td data-label="Fecha">{{ \Illuminate\Support\Carbon::parse($evento->fecha_hora)->format('d/m/Y H:i') }}</td><td data-label="Estado">{{ ucfirst(str_replace('_', ' ', $evento->pivot->estado)) }}</td><td data-label="Acciones"><a class="boton boton--linea boton--pequeno" href="{{ route('evento.paginaInterna', $evento->id) }}">Ver evento</a></td></tr>@endforeach</tbody></table></div>@endif</section>
<section class="panel socio-historial__grupo" aria-labelledby="historial-compras"><h3 class="panel__titulo" id="historial-compras">Compras</h3>@if ($compras->isEmpty())<p class="texto-suave">No tienes compras registradas.</p>@else<div class="tabla-envoltura"><table class="tabla tabla--apilada"><thead><tr><th>Libro</th><th>Fecha</th><th>Precio</th><th>Estado</th></tr></thead><tbody>@foreach ($compras as $compra)<tr><td data-label="Libro">{{ $compra->libro->titulo ?? 'Libro no disponible' }}</td><td data-label="Fecha">{{ $compra->fecha_compra?->format('d/m/Y') ?? '—' }}</td><td data-label="Precio">{{ number_format((float) $compra->precio, 2, ',', '.') }} €</td><td data-label="Estado">{{ ucfirst($compra->estado) }}</td></tr>@endforeach</tbody></table></div>@endif</section>
<section class="panel socio-historial__grupo" aria-labelledby="historial-publicaciones"><h3 class="panel__titulo" id="historial-publicaciones">Publicaciones</h3>@if ($publicaciones->isEmpty())<p class="texto-suave">No tienes publicaciones registradas.</p>@else<div class="tabla-envoltura"><table class="tabla tabla--apilada"><thead><tr><th>Título</th><th>Libro</th><th>Formato</th><th>Fecha</th><th></th></tr></thead><tbody>@foreach ($publicaciones as $publicacion)<tr><td data-label="Título">{{ $publicacion->titulo_publicacion }}</td><td data-label="Libro">{{ $publicacion->nombre_libro }}</td><td data-label="Formato">{{ strtoupper($publicacion->archivo_extension) }}</td><td data-label="Fecha">{{ $publicacion->fecha_publicacion?->format('d/m/Y') ?? '—' }}</td><td data-label="Acciones"><a class="boton boton--linea boton--pequeno" href="{{ route('usuario.publicar.archivo', $publicacion->id) }}">Abrir archivo</a></td></tr>@endforeach</tbody></table></div>@endif</section></div>
